contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dep, uint256 wit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        require(dep > 0);
        require(wit < dep);
        require(address(this).balance >= dep);

        c.deposit{value: dep}(); if (__ESBMC_reverted()) return;
        c.withdraw(wit); if (__ESBMC_reverted()) return;

        uint256 contractBefore = address(c).balance;
        uint256 callerBefore = address(this).balance;

        c.refund(); if (__ESBMC_reverted()) return;

        assert(address(this).balance - callerBefore == dep - wit &&
               contractBefore - address(c).balance == dep - wit);
    }

    receive() external payable {}
}

