pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 dep, uint256 wit) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(dep > 0);
        vm.assume(wit < dep);
        vm.assume(address(this).balance >= dep);
        try c.deposit{value: dep}() {} catch { return; }
        try c.withdraw(wit) {} catch { return; }
        uint256 contractBefore = address(c).balance;
        uint256 callerBefore = address(this).balance;
        try c.refund() {} catch { return; }
        assertTrue(address(this).balance - callerBefore == dep - wit &&
               contractBefore - address(c).balance == dep - wit);
    }

    function testFuzz_run(uint256 dep, uint256 wit) public {
        _run(dep, wit);
    }

    receive() external payable {}
}
